<?php $base='/saves/'.(int)$context->saveId(); ?>
<div class="page-heading"><div><span class="eyebrow">Cellule recrutement</span><h1>Transferts</h1><p>Budget disponible : <strong><?= format_money($context->club()['transfer_budget']) ?></strong></p></div><span class="badge <?= $windowOpen?'badge--success':'badge--danger' ?>"><?= $windowOpen?'Marché ouvert':'Marché fermé' ?></span></div>
<div class="tabs" data-tabs><?php foreach(['search'=>'Recherche','offers'=>'Offres ('.count($offers).')','shortlist'=>'Suivis ('.count($shortlistPlayers).')','history'=>'Historique'] as $key=>$label): ?><button class="<?= $tab===$key?'active':'' ?>" data-tab="<?= $key ?>"><?= $label ?></button><?php endforeach; ?></div>
<section class="tab-panel <?= $tab==='search'?'':'is-hidden' ?>" data-tab-panel="search"><div class="panel"><div class="panel__header"><h2>Recherche avancée</h2></div><div class="panel__body"><form method="get" class="filter-form filter-form--wrap"><input type="hidden" name="tab" value="search"><label>Nom<input name="q" value="<?= e($filters['q']??'') ?>" placeholder="Joueur…"></label><label>Poste<select name="position"><option value="">Tous</option><?php foreach(['GK','DL','DC','DR','WBL','WBR','MDC','MC','AMC','ML','MR','ST'] as $position): ?><option value="<?= $position ?>" <?= ($filters['position']??'')===$position?'selected':'' ?>><?= $position ?></option><?php endforeach; ?></select></label><label>Club<select name="club_id"><option value="">Tous</option><?php foreach($clubs as $club): ?><option value="<?= (int)$club['id'] ?>" <?= (int)($filters['club_id']??0)===(int)$club['id']?'selected':'' ?>><?= e($club['name']) ?></option><?php endforeach; ?></select></label><label>OVR min.<input type="number" name="min_ovr" min="1" max="99" value="<?= e($filters['min_ovr']??'') ?>"></label><label>Âge max.<input type="number" name="max_age" min="16" max="45" value="<?= e($filters['max_age']??'') ?>"></label><label>Valeur max.<input type="number" name="max_value" min="0" value="<?= e($filters['max_value']??'') ?>"></label><label>Contrat<select name="contract"><option value="">Tous</option><option value="expiring" <?= ($filters['contract']??'')==='expiring'?'selected':'' ?>>Expire sous 12 mois</option><option value="free" <?= ($filters['contract']??'')==='free'?'selected':'' ?>>Sans contrat</option></select></label><label class="check-field"><input type="checkbox" name="free_agent" value="1" <?= !empty($filters['free_agent'])?'checked':'' ?>>Joueurs libres</label><button class="btn btn--primary">Filtrer</button></form></div></div>
<div class="transfer-list"><?php foreach($results as $player): $own=(int)$player['club_id']===$context->clubId(); ?><article class="panel transfer-player"><div class="transfer-player__summary"><a class="player-link" href="<?= $base ?>/players/<?= (int)$player['id'] ?>"><?= player_portrait($player, 'sm') ?><span><strong><?= e($player['first_name'].' '.$player['last_name']) ?></strong><small><?= e($player['club_name']??'Joueur libre') ?></small></span></a><span class="position-badge"><?= e($player['primary_position']) ?></span><span><?= player_age($player['birth_date'],$context->save()['current_date']) ?> ans</span><span class="rating rating--<?= $player['overall_rating']>=70?'high':'mid' ?>"><?= (int)$player['overall_rating'] ?></span><strong><?= format_money($player['market_value']) ?></strong><form method="post" action="<?= $base ?>/transfers/shortlist/<?= (int)$player['id'] ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="icon-button" title="Suivre"><?= isset($shortlist[(int)$player['id']])?'★':'☆' ?></button></form></div><details><summary>Négocier</summary><form method="post" action="<?= $base ?>/transfers/offers" class="negotiation-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="player_id" value="<?= (int)$player['id'] ?>"><input type="hidden" name="direction" value="<?= $own?'sell':'buy' ?>"><label>Type<select name="offer_type"><option value="purchase">Achat / transfert</option><?php if($player['club_id']): ?><option value="loan">Prêt</option><?php endif; ?></select></label><?php if($own): ?><label>Acheteur<select name="to_club_id" required><?php foreach($clubs as $club): if((int)$club['id']===$context->clubId())continue; ?><option value="<?= (int)$club['id'] ?>"><?= e($club['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?><label>Montant<input type="number" name="amount" min="0" step="1000" value="<?= (int)round($player['market_value']*1.15) ?>" required></label><label>Salaire / sem.<input type="number" name="wage" min="0" step="50" value="<?= (int)max(500,($player['contract_salary']??$player['overall_rating']**2*.5)*1.15) ?>" required></label><label>Durée (années)<input type="number" name="contract_years" min="1" max="5" value="3"></label><label>Prime<input type="number" name="signing_bonus" min="0" value="0"></label><label>Prêt (mois)<input type="number" name="loan_duration_months" min="1" max="24" value="6"></label><label>Salaire prêt %<input type="number" name="loan_wage_share" min="0" max="100" value="100"></label><label>Option d’achat<input type="number" name="buy_option" min="0" value="0"></label><button class="btn btn--primary" <?= !$windowOpen?'disabled':'' ?>>Envoyer l’offre</button></form></details></article><?php endforeach; ?><?php if(!$results): ?><div class="empty-state"><p>Aucun joueur ne correspond à ces filtres.</p></div><?php endif; ?></div></section>
<section class="tab-panel <?= $tab==='offers'?'':'is-hidden' ?>" data-tab-panel="offers"><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Joueur</th><th>De / vers</th><th>Type</th><th>Montant</th><th>Salaire</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($offers as $offer): ?><tr><td><?= e($offer['first_name'].' '.$offer['last_name']) ?><small><?= e($offer['primary_position']) ?> · <?= (int)$offer['overall_rating'] ?></small></td><td><?= e($offer['from_name']??'Libre') ?> → <?= e($offer['to_name']??'Libre') ?></td><td><?= e($offer['offer_type']) ?></td><td><?= format_money($offer['amount']) ?></td><td><?= format_money($offer['wage']) ?></td><td><span class="badge <?= $offer['status']==='accepted'?'badge--success':($offer['status']==='rejected'?'badge--danger':'') ?>"><?= e($offer['status']) ?></span></td><td><?php if($offer['status']==='pending'): ?><div class="offer-actions"><form method="post" action="<?= $base ?>/transfers/offers/<?= (int)$offer['id'] ?>/accept"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="btn btn--sm btn--primary">Accepter</button></form><form method="post" action="<?= $base ?>/transfers/offers/<?= (int)$offer['id'] ?>/reject"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="btn btn--sm btn--ghost">Refuser</button></form><details><summary>Contre-offre</summary><form method="post" action="<?= $base ?>/transfers/offers/<?= (int)$offer['id'] ?>/counter" class="counter-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="number" name="amount" value="<?= (int)$offer['amount'] ?>" min="0"><input type="number" name="wage" value="<?= (int)$offer['wage'] ?>" min="0"><button class="btn btn--sm">Envoyer</button></form></details></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></section>
<section class="tab-panel <?= $tab==='shortlist'?'':'is-hidden' ?>" data-tab-panel="shortlist"><div class="panel"><div class="panel__body transfer-list"><?php foreach($shortlistPlayers as $player): ?><div class="shortlist-row"><a href="<?= $base ?>/players/<?= (int)$player['id'] ?>"><?= e($player['first_name'].' '.$player['last_name']) ?></a><span><?= e($player['club_name']??'Libre') ?></span><strong><?= (int)$player['overall_rating'] ?></strong><form method="post" action="<?= $base ?>/transfers/shortlist/<?= (int)$player['id'] ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="btn btn--sm btn--ghost">Retirer</button></form></div><?php endforeach; ?><?php if(!$shortlistPlayers): ?><div class="empty-state"><p>Ajoutez des joueurs avec l’étoile dans la recherche.</p></div><?php endif; ?></div></div></section>
<section class="tab-panel <?= $tab==='history'?'':'is-hidden' ?>" data-tab-panel="history"><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Joueur</th><th>De</th><th>Vers</th><th>Type</th><th>Montant</th></tr></thead><tbody><?php foreach($history as $transfer): ?><tr><td><?= format_date($transfer['transfer_date']) ?></td><td><?= e($transfer['first_name'].' '.$transfer['last_name']) ?></td><td><?= e($transfer['from_name']??'Libre') ?></td><td><?= e($transfer['to_name']??'Libre') ?></td><td><?= e($transfer['type']) ?></td><td><?= format_money($transfer['fee']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></section>
